{
  "book_code": "JASHER",
  "verses": [
    {
      "chapter": 1,
      "verse": 1,
      "text_ar": "وقال الله: لنصنع الإنسان على صورتنا، على شبهنا، فخلق الله الإنسان على صورته الخاصة."
    },
    {
      "chapter": 1,
      "verse": 2,
      "text_ar": "فشكل الله الإنسان من التراب، ونفخ في أنفه نسمة الحياة، فأصبح الإنسان نفسًا حيةً متمكنةً من الكلام."
    },
    {
      "chapter": 1,
      "verse": 3,
      "text_ar": "وقال الرب: ليس من الجيد أن يكون الإنسان وحيدًا؛ سأصنع له معاونًا."
    },
    {
      "chapter": 1,
      "verse": 4,
      "text_ar": "وأسقط الرب نومًا عميقًا على آدم، فنام، فأخذ إحدى أضلاعه، فصنع لحمًا عليها، وشكّلها وأحضرها إلى آدم، فاستفاق آدم من نومه فوجد امرأة تقف أمامه."
    },
    {
      "chapter": 1,
      "verse": 5,
      "text_ar": "فقال: هذه عظم من عظامي وتدعى امرأة، لأنها أُخذت من رجل؛ فسمى آدمُها حواء، لأنها أم جميع الأحياء."
    },
    {
      "chapter": 1,
      "verse": 6,
      "text_ar": "باركهم الله ودعا اسميهما آدم وحواء في اليوم الذي خلقهما فيه، وقال رب الله: اثراوا وتكاثروا واملأوا الأرض."
    },
    {
      "chapter": 1,
      "verse": 7,
      "text_ar": "وأخذ رب الله آدم وزوجته، ووضعهما في جنّة عدن ليعملوا فيها ويحافظوا عليها؛ فأمرهما وقال لهما: من كل شجرة في الجنة تأكلون، لكن من شجرة معرفة الخير والشر لا تأكلون، ففي اليوم الذي تأكلون فيها ستموتون بالتأكيد."
    },
    {
      "chapter": 1,
      "verse": 8,
      "text_ar": "وعندما باركهم الله وأمرهم، رحل عنهم، فكان آدم وزوجته يسكنان الجنة وفقًا للأمر الذي أصدره الرب لهما."
    },
    {
      "chapter": 1,
      "verse": 9,
      "text_ar": "فجاء الثعبان، الذي خلقه الله معهم على الأرض، إليهما ليحثهما على خرق أمر الله الذي أوصاهما به."
    },
    {
      "chapter": 1,
      "verse": 10,
      "text_ar": "فأغرى الثعبان المرأة لتأكل من شجرة المعرفة، واستجابت المرأة لصوت الثعبان، فخالفت كلمة الله، فأخذت من شجرة معرفة الخير والشر فأكلت، ثم أخذت منها وأعطتها لزوجها فأكل هو أيضًا."
    }
  ]
}
